<?php declare(strict_types=1);$e=static fn(mixed $v):string=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8'); ?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Rental agreements | Triple R Gensan</title><link rel="stylesheet" href="/assets/css/app.css"></head><body><header class="topbar"><a class="brand" href="/staff">Triple R Gensan</a><nav class="staff-actions"><a href="/rentals">Agreements</a><a href="/customers">Customers</a><a href="/fleet/vehicles">Fleet</a></nav></header><main class="page-shell"><section class="page-heading"><div><p class="eyebrow">Rental management</p><h1>Agreements</h1></div><?php if(in_array($user['role'],['system_admin','front_desk'],true)):?><a class="button-link" href="/rentals/new">New reservation</a><?php endif;?></section><form class="panel filter-form" method="get" action="/rentals"><label>Status<select name="status"><option value="">All statuses</option><?php foreach($statuses as $s):?><option value="<?= $e($s) ?>"<?= $status===$s?' selected':'' ?>><?= $e(str_replace('_',' ',$s)) ?></option><?php endforeach;?></select></label><button type="submit">Filter</button></form><section class="panel"><div class="table-wrap"><table><thead><tr><th>Agreement</th><th>Customer</th><th>Vehicle</th><th>Dates</th><th>Days</th><th>Base</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><a href="/rentals/detail?agreement_id=<?= (int)$r['agreement_id'] ?>">#<?= (int)$r['agreement_id'] ?></a></td><td><?= $e($r['customer_name']) ?></td><td><?= $e($r['plate_number'].' '.$r['make'].' '.$r['model']) ?></td><td><?= $e($r['start_date'].' – '.$r['end_date']) ?></td><td><?= (int)$r['rental_days'] ?></td><td>₱<?= $e($r['base_amount']) ?></td><td><?= $e($r['status']) ?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="7">No agreements found.</td></tr><?php endif;?></tbody></table></div></section></main></body></html>
